"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def levelOrder(root):
    if (root is None):
        return []
    queue = [root]
    result = []
    while (len(queue) > 0):
        level = []
        nextQueue = []
        for node in queue:
            level.append(node.value)
            if (node.left is not None):
                nextQueue.append(node.left)
            if (node.right is not None):
                nextQueue.append(node.right)
        result.append(level)
        queue = nextQueue
    return result
